import assert from 'node:assert/strict';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
import {writeFile} from 'node:fs/promises';
const exec=promisify(execFile);
const root='<isolated-capture-fixture>';
const mode=process.argv[2]??'version';
const memory=process.argv[3]??'128';
assert.ok(['128','512'].includes(memory));
const name=`gaffer-harness-probe-${mode}-${memory}-${Date.now()}`;
const image='node:24-bookworm@sha256:6dac556d980b7f0e5498d08f08cee0ca67798b4ad6c23964a9214920e67758d0';
const evidence:any={name,mode,memoryMiB:Number(memory),acceptedIsolationProfile:memory==='128',image,started:new Date().toISOString(),cleanup:false,commands:[]};
const run=async(args:string[],timeout=15000)=>{evidence.commands.push(args);return await exec('docker',['--context','desktop-linux',...args],{timeout,maxBuffer:4*1024*1024});};
await writeFile(`${root}/${mode}-${memory}-evidence.json`,JSON.stringify(evidence,null,2)+'\n');
try {
 const v=JSON.parse((await run(['version','--format','{{json .}}'])).stdout);
 assert.equal(v.Server.Version,'29.7.2');assert.equal(v.Server.KernelVersion,'6.12.76-linuxkit');assert.equal(v.Server.Arch,'arm64');
 evidence.runtime=v.Server;
 await run(['create','--name',name,'--label',`dev.gaffer.harness-probe=${name}`,'--platform','linux/arm64','--pull','never','--network','none','--user','1000:1000','--cap-drop','ALL','--security-opt','no-new-privileges=true','--read-only','--init','--cgroupns','private','--ipc','private','--cpus','0.5','--memory',memory+'m','--memory-swap',memory+'m','--pids-limit','64','--ulimit','nofile=256:256','--ulimit','core=0:0','--shm-size','4m','--tmpfs','/work:rw,exec,nosuid,nodev,size=32m,nr_inodes=4096,uid=1000,gid=1000,mode=0700','--tmpfs','/tmp:rw,noexec,nosuid,nodev,size=8m,nr_inodes=1024,uid=1000,gid=1000,mode=0700','--mount',`type=bind,source=${root},target=/fixture,readonly`,'--workdir','/work','--log-driver','local','--log-opt','max-size=1m','--log-opt','max-file=1','--log-opt','compress=false','--restart','no',image,'/usr/bin/env','-i','PATH=/usr/local/bin:/usr/bin:/bin','HOME=/work','XDG_CONFIG_HOME=/work/config','XDG_DATA_HOME=/work/data','XDG_CACHE_HOME=/work/cache','XDG_STATE_HOME=/work/state',...(mode==='version'?['/fixture/opencode','--version']:['node','/fixture/probe.ts',mode])]);
 const s=JSON.parse((await run(['inspect',name])).stdout)[0];evidence.preflight=s;
 assert.equal(s.Config.User,'1000:1000');assert.equal(s.HostConfig.NetworkMode,'none');assert.equal(s.HostConfig.ReadonlyRootfs,true);assert.equal(s.HostConfig.Memory,Number(memory)*1024*1024);assert.equal(s.Mounts.length,1);assert.equal(s.Mounts[0].RW,false);assert.deepEqual(s.HostConfig.CapDrop,['ALL']);assert.equal(s.HostConfig.Init,true);
 await run(['start',name]);
 try{evidence.exit=Number((await run(['wait',name],45000)).stdout.trim());}catch(e:any){evidence.timeout=e.message; evidence.beforeStop=(await run(['top',name,'-eo','pid,ppid,comm'])).stdout; await run(['stop','--timeout','1',name]);}
 const logs=await run(['logs',name]);evidence.stdout=logs.stdout;evidence.stderr=logs.stderr;
 evidence.final=JSON.parse((await run(['inspect',name])).stdout)[0].State;
 console.log(JSON.stringify({exit:evidence.exit,final:evidence.final,stdout:evidence.stdout,stderr:evidence.stderr}));
}catch(e:any){evidence.error=e.stack;console.error(e.message);process.exitCode=1;}
finally {
 const s=JSON.parse((await run(['inspect',name])).stdout)[0];assert.equal(s.Config.Labels['dev.gaffer.harness-probe'],name);await run(['rm','-f',name]);assert.equal((await run(['ps','-aq','--filter',`label=dev.gaffer.harness-probe=${name}`])).stdout.trim(),'');evidence.cleanup=true;await writeFile(`${root}/${mode}-${memory}-evidence.json`,JSON.stringify(evidence,null,2)+'\n');
}

