import {createServer} from 'node:http';
import {spawn,execFileSync} from 'node:child_process';
import {mkdirSync,writeFileSync,readFileSync,readdirSync} from 'node:fs';
const mode=process.argv[2];
const log=(type:string, data:any)=>console.log(JSON.stringify({probe:type,time:Date.now(),...data}));
mkdirSync('/work/repo');writeFileSync('/work/repo/greeting.txt','hello\n');
execFileSync('git',['init','-q','/work/repo']);execFileSync('git',['-C','/work/repo','add','.']);execFileSync('git',['-C','/work/repo','-c','user.name=Probe','-c','user.email=probe@example.invalid','commit','-qm','Synthetic public-domain fixture']);
log('base',{sha:execFileSync('git',['-C','/work/repo','rev-parse','HEAD'],{encoding:'utf8'}).trim()});
let count=0;
const server=createServer(async(req,res)=>{
 let text='';for await (const c of req){text+=c;if(text.length>300000){res.writeHead(413).end();return;}}
 const body=JSON.parse(text);log('request',{count:++count,method:req.method,path:req.url,headers:{...req.headers,authorization:'<dummy-redacted>'},body});
 res.on('close',()=>log('response-close',{count,ended:res.writableEnded}));
 if(count>3){res.writeHead(429).end(JSON.stringify({error:{message:'probe request cap'}}));return;}
 if(mode==='strict'){res.writeHead(400,{'content-type':'application/json'}).end(JSON.stringify({error:{message:'Unsupported field: max_tokens',type:'invalid_request_error',code:'unsupported_field'}}));return;}
 if(mode==='stall'){return;}
 res.writeHead(200,{'content-type':'text/event-stream','cache-control':'no-cache'});
 const delta=(d:any,finish:any=null)=>res.write('data: '+JSON.stringify({id:`chatcmpl-probe-${count}`,object:'chat.completion.chunk',created:1,model:'probe-model',choices:[{index:0,delta:d,finish_reason:finish}]})+'\n\n');
 delta({role:'assistant',content:''});
 if(mode==='edit'&&count===1){delta({tool_calls:[{index:0,id:'call_probe_edit_1',type:'function',function:{name:'edit',arguments:'{"filePath":"/work/repo/greeting.txt",'}}]});delta({tool_calls:[{index:0,function:{arguments:'"oldString":"hello","newString":"hello from probe"}'}}]});delta({},'tool_calls');}
 else {delta({content:'Synthetic probe '});delta({content:'complete.'});delta({},'stop');}
 res.end('data: [DONE]\n\n');
});
server.listen(8765,'127.0.0.1');
const config={enabled_providers:['probe'],model:'probe/probe-model',small_model:'probe/probe-model',share:'disabled',autoupdate:false,snapshot:false,formatter:false,lsp:false,mcp:{},plugin:[],instructions:[],permission:{'*':'deny',edit:mode==='edit'?'allow':'deny'},provider:{probe:{npm:'@ai-sdk/openai-compatible',name:'Synthetic probe',options:{includeUsage:false,baseURL:'http://127.0.0.1:8765/v1',apiKey:'dummy-not-provider'},models:{'probe-model':{name:'Probe',tool_call:true,limit:{context:8192,output:128},modalities:{input:['text'],output:['text']}}}}},experimental:{openTelemetry:false}};
writeFileSync('/work/config.json',JSON.stringify(config));log('config',{config});
const env:any={PATH:'/usr/local/bin:/usr/bin:/bin',HOME:'/work',XDG_CONFIG_HOME:'/work/config',XDG_DATA_HOME:'/work/data',XDG_CACHE_HOME:'/work/cache',XDG_STATE_HOME:'/work/state',OPENCODE_CONFIG:'/work/config.json',OPENCODE_EXPERIMENTAL_OUTPUT_TOKEN_MAX:'128',OPENCODE_EXPERIMENTAL_NATIVE_LLM:'false'};
for(const k of ['DISABLE_PROJECT_CONFIG','PURE','DISABLE_DEFAULT_PLUGINS','DISABLE_EXTERNAL_SKILLS','DISABLE_CLAUDE_CODE','DISABLE_LSP_DOWNLOAD','DISABLE_MODELS_FETCH','DISABLE_AUTOUPDATE','DISABLE_AUTOCOMPACT','EXPERIMENTAL_DISABLE_FILEWATCHER'])env['OPENCODE_'+k]='1';
const child=spawn('/fixture/opencode',['run','--format','json','--model','probe/probe-model','--title','Fixed synthetic probe','Change greeting.txt from hello to hello from probe.'],{cwd:'/work/repo',env,stdio:['ignore','pipe','pipe']});
child.stdout.on('data',x=>log('native-stdout',{chunk:x.toString()}));child.stderr.on('data',x=>log('native-stderr',{chunk:x.toString()}));
const deadline=setTimeout(()=>{log('deadline',{pid:child.pid});child.kill('SIGTERM');setTimeout(()=>child.kill('SIGKILL'),1000).unref();},25000);
child.on('exit',(code,signal)=>{clearTimeout(deadline);log('exit',{code,signal,requests:count,file:readFileSync('/work/repo/greeting.txt','utf8'),diff:execFileSync('git',['-C','/work/repo','diff'],{encoding:'utf8'})});server.closeAllConnections();server.close();});
